<?php
declare(strict_types=1);
require __DIR__.'/fixtures.php';
use Greenwood\Crypto\Ed25519KeyPair;
use Greenwood\Economics\{Policy,CanonicalJson,Ledger};
$f=fixture(true);$council=[];for($i=0;$i<3;$i++)$council[]=Ed25519KeyPair::generate();
$new=[];for($i=0;$i<5;$i++)$new[]=Ed25519KeyPair::generate();$guardian=Ed25519KeyPair::generate();
$f['p']['recovery_policy']=['version'=>1,'enabled'=>true,'keys'=>array_map(fn($k)=>bin2hex($k->getPublicKey()),$council),'threshold'=>2,'timelock_blocks'=>3,'proposal_lifetime_blocks'=>20,'veto_threshold'=>2];
$f['g']->configureEconomics($f['p']);$s=$f['g']->initialState();$chain=$f['g']->getChainId();
$proposal=['action'=>'recovery_propose','nonce'=>0,'signers'=>array_map(fn($k)=>bin2hex($k->getPublicKey()),$new),'guardians'=>[bin2hex($guardian->getPublicKey())],'reason_hash'=>str_repeat('a',64)];
$assertReject=static function($key,$a,$height,$label)use(&$s,$chain){$root=$s->getStateRoot();rejects(fn()=>act($s,$key,$a,$height,$chain),$label);check($root===$s->getStateRoot(),'Rejected recovery leaves all state unchanged');};
$legacy=fixture(true);$ls=$legacy['g']->initialState();rejects(fn()=>act($ls,$legacy['signers'][0],$proposal,1,$legacy['g']->getChainId()),'No default recovery authority');
$bad=$f['p'];$bad['recovery_policy']['keys'][0]=$bad['signers'][0];rejects(fn()=>Policy::validate($bad),'No key reuse between council and ordinary governance');
$bad=$f['p'];$bad['recovery_policy']['threshold']=1;rejects(fn()=>Policy::validate($bad),'Minority cannot recover governance');
$bad=$f['p'];$bad['recovery_policy']['timelock_blocks']=0;rejects(fn()=>Policy::validate($bad),'No immediate recovery');
$assertReject($f['signers'][0],$proposal,1,'Ordinary signer cannot act as council');
$assertReject($council[0],$proposal+['amount'=>'1'],1,'Recovery cannot request spending');
$bad=$proposal;$bad['signers'][0]=$f['p']['recovery_policy']['keys'][0];$assertReject($council[0],$bad,1,'Recovery council cannot install its own recovery key as treasury signer');
$payment=propose($s,$f,'grants',100,1);act($s,$council[0],$proposal,1,$chain);$id=$s->economicSummary()['recovery_state']['proposal']['id'];
$assertReject($council[0],$proposal,1,'Only one active recovery');
act($s,$council[0],['action'=>'recovery_approve','proposal'=>$id],1,$chain);
$assertReject($council[0],['action'=>'recovery_approve','proposal'=>$id],1,'No duplicate quorum counting');
$assertReject($council[0],['action'=>'recovery_execute','proposal'=>$id],1,'No subquorum recovery');
act($s,$council[1],['action'=>'recovery_approve','proposal'=>$id],1,$chain);
check($s->economicSummary()['recovery_state']['proposal']['ready']===4,'Timelock starts when quorum is reached');
$assertReject($council[0],['action'=>'recovery_execute','proposal'=>$id],1,'No early recovery');
$veto=clone $s;act($veto,$f['signers'][0],['action'=>'recovery_veto','proposal'=>$id],1,$chain);act($veto,$f['signers'][1],['action'=>'recovery_veto','proposal'=>$id],1,$chain);
check($veto->economicSummary()['recovery_state']['proposal']===null&&$veto->economicSummary()['recovery_state']['last_event']['status']==='vetoed','Configured existing authority can veto recovery');
rejects(fn()=>act($veto,$council[0],['action'=>'recovery_execute','proposal'=>$id],1,$chain),'Veto cannot be replayed as execution');
$expired=clone $s;advance($expired,21);rejects(fn()=>act($expired,$council[0],['action'=>'recovery_execute','proposal'=>$id],22,$chain),'Expired quorum cannot execute');
advance($s,3);$before=$s->economicSummary();act($s,$council[0],['action'=>'recovery_execute','proposal'=>$id],4,$chain);$after=$s->economicSummary();
check($after['policy']['signers']===$proposal['signers']&&$after['policy']['guardians']===$proposal['guardians'],'Approved recovery replaces only designated custody');
check($after['balances']===$before['balances']&&$after['services']===$before['services'],'Recovery cannot spend reserves or change accepted commitments');
$allowed=$before['policy'];$allowed['signers']=$proposal['signers'];$allowed['guardians']=$proposal['guardians'];check($allowed===$after['policy'],'Allocation fees limits recipients and recovery authority remain unchanged');
check($after['policy_version']===2&&$after['proposals'][$payment]['status']==='invalidated','Old authorizations are invalidated after custody rotation');
$assertReject($council[0],['action'=>'recovery_execute','proposal'=>$id],4,'Recovery execution is not replayable');
$assertReject($f['signers'][0],['action'=>'approve','proposal'=>$payment],4,'Lost authority cannot approve after recovery');
$decoded=CanonicalJson::decode(CanonicalJson::encode($after));check(CanonicalJson::encode(Ledger::restore($decoded)->snapshot())===CanonicalJson::encode($after),'Recovery audit survives canonical snapshot restoration');
$replacement=$after['policy'];$replacement['recovery_policy']=['enabled'=>false];$assertReject($new[0],['action'=>'propose','kind'=>'policy','reserve'=>'institute_treasury','nonce'=>0,'expires'=>30000,'replacement'=>$replacement],4,'Ordinary rotation cannot silently disable recovery');
$newId=propose($s,array_replace($f,['signers'=>$new]),'grants',100,4);check(isset($s->economicSummary()['proposals'][$newId]),'Restored signers can resume ordinary governed work');
echo json_encode(['status'=>'PASS','checks'=>$checks,'production_recovery_authorized'=>false],JSON_PRETTY_PRINT)."\n";
